import React, { useState, useEffect } from "react";
import "./TeamRegistration.css";
import { broadcastUpdate } from "./BroadcastState";

function TeamRegistration() {
  const [teamName, setTeamName] = useState([]);
  const [idx, setIdx] = useState(0);

  // Allow alphanumeric characters and space
  const VALID_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890 ";

  // Handle key input
  useEffect(() => {
    const handleKeyUp = (e) => {
      if (e.key && VALID_CHARS.includes(e.key)) {
        setTeamName(prevTeamName => {
          const newTeamName = [...prevTeamName];
          newTeamName[idx] = e.key;
          return newTeamName;
        });
        setIdx(prevIdx => prevIdx + 1);
      }
      // Enter key handler - redirect to countdown
      else if (e.keyCode === 13 && teamName.length > 0) {
        const name = teamName.join("");
        // Store team name in localStorage and broadcast to other tabs
        localStorage.setItem("teamName", name);
        broadcastUpdate("teamName", name);
        
        // Redirect to countdown page and force reload to render the component
        window.location.hash = "#intro";
        window.location.reload();
      }
    };

    window.document.addEventListener("keyup", handleKeyUp);
    return () => {
      window.document.removeEventListener("keyup", handleKeyUp);
    };
  }, [idx, teamName]);

  // Handle backspace key
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.keyCode === 8 || e.keyCode === 46) {
        if (idx > 0) {
          setTeamName(prevTeamName => {
            const newTeamName = [...prevTeamName];
            newTeamName.pop();
            return newTeamName;
          });
          setIdx(prevIdx => prevIdx - 1);
        }
      }
    };

    window.document.addEventListener("keydown", handleKeyDown);
    return () => {
      window.document.removeEventListener("keydown", handleKeyDown);
    };
  }, [idx]);

  return (
    <div className="TeamRegistration">
      <div className="title">
        <p>Enter Team Name</p>
      </div>
      <div className="msgLine input">
        {teamName.map((char, i) => (
          <div key={i} className="teamChar">
            {char}
          </div>
        ))}
        <div className="teamChar empty">
          <div className="cursor">_</div>
        </div>
      </div>
      <div className="instructions">
        <p>Press Enter when complete</p>
      </div>
    </div>
  );
}

export default TeamRegistration;