import React, { useState, useEffect } from "react";
import "./Scoreboard.css";

function Scoreboard() {
  const [scores, setScores] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    const ms = Math.floor((seconds % 1) * 1000);
    return `${mins}:${secs.toString().padStart(2, '0')}:${ms.toString().padStart(3, '0')}`;
  };

  const formatDate = (epochTime) => {
    const date = new Date(epochTime);
    const hours = date.getHours().toString().padStart(2, '0');
    const minutes = date.getMinutes().toString().padStart(2, '0');
    const day = date.getDate();
    const month = date.getMonth() + 1;
    const year = date.getFullYear();
    return `${hours}:${minutes} ${day}/${month}/${year}`;
  };

  useEffect(() => {
    const fetchScores = async () => {
      try {
        const origin = window.location.origin;
        console.log("Origin value:", origin);
        const response = await fetch("https://escape-room-db-proxy.hursley-escape-room.workers.dev/top10", {
          headers: {
            Origin: origin
          }
        });
        if (!response.ok) {
          throw new Error(`HTTP error! Status: ${response.status}`);
        }
        const data = await response.json();
        setScores(data);
        setLoading(false);
      } catch (error) {
        setError(error.message);
        setLoading(false);
      }
    };

    fetchScores();
  }, []);

  return (
    <div className="Scoreboard">
      <div className="title">
        <p>Top 10 Teams</p>
      </div>
      
      {loading && (
        <div className="loading">Loading scores...</div>
      )}
      
      {error && (
        <div className="error">Error loading scores: {error}</div>
      )}
      
      {!loading && !error && (
        <div className="scoreTable">
          <div className="tableHeader">
            <div className="headerCell">Team</div>
            <div className="headerCell">Time</div>
            <div className="headerCell">Date</div>
          </div>
          
          {scores.map((score, index) => (
            <div key={index} className="tableRow">
              <div className="cell">{score.teamname}</div>
              <div className="cell">{formatTime(score.time)}</div>
              <div className="cell">{formatDate(score.date)}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default Scoreboard;
