import React, { useEffect, useState } from 'react';
import { broadcastEvent, subscribeToEvent, subscribeToUpdates } from '../../BroadcastState';
import { GAME_TIME } from '../../Countdown';
import './side-channel.css';

//******************************************** Admin mode ********************************************//
// These variables are used to create the password_hash.
//
// 1. Set the 'admin' true and 'password' as you want.
//  e.g.
//    const admin = true;
//    const password = "AB34EF78";
//
// 2. Run the app, and you will see the hash values in the console.
// 2.1. You can find the console by using web browser's inspect mode.
//
// 3. Copy those values into 'password_hash' variable below.
//  e.g.
//     const password_hash = [
//       "86a7f47b333770c6e85f03ee3caa6ef9dfebfe2cb3444b738cc2df5d177ce38a",
//       "0e6fac6a3ad129a64c2b9d6eaf6680e4b5f95dcd36949dad585415b017633875",
//       "dffa6bca874e9206a6b320ea6a51555d0ab7076bb05c88574dffcc69095efa23",
//       "4414cdcb7cc80ae51939e6a62686e947b0e73ce636857d8d4d4e883d48a63a96",
//     ]
//
// 4. you must set the admin to false and the password to empty string:
//  e.g.
//     const admin = false;
//     const password = "";
//
const admin = true;
const password = localStorage.getItem('escape.sc.password') || '72756242';
console.debug(password);

// You must get the password hash using the admin mode, which is explained above this comment.
const password_hash = [
  '8722616204217eddb39e7df969e0698aed8e599ba62ed2de1ce49b03ade0fede',
  'f369cb89fc627e668987007d121ed1eacdc01db9e28f8bb26f358b7d8c4f08ac',
  '81b8a03f97e8787c53fe1a86bda042b6f0de9b0ec9c09357e107c99ba4d6948a',
  '73475cb40a568e8da8a045ced110137e159f890ac4da883b6b17dc651b3a8049',
];

//****************************************************************************************************//

// The list of characters we consider valid for input
const VALID_CHARS = 'abcdefghijklmnopqrstuvwxyz1234567890';
// Addditional character we allow but won't be manipulated
const SPECIAL_CHARS = '';

// input string(2-digit code), output hash values
// This function is used not to hard-code passcodes in the source code
async function digestMessage(message) {
  const msgUint8 = new TextEncoder().encode(message); // encode as (utf-8) Uint8Array
  const hashBuffer = await window.crypto.subtle.digest('SHA-256', msgUint8); // hash the message
  const hashArray = Array.from(new Uint8Array(hashBuffer)); // convert buffer to byte array
  const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join(''); // convert bytes to hex string
  return hashHex;
}

// delay time function
function timeout(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// Check if input hash is in the correct order and matched with 2-digit passcodes
async function isCorrectPass(hash, i) {
  for (let j = 0; j < password_hash[i].length; j++) {
    await timeout(30);
    if (hash[j] !== password_hash[i][j]) {
      await timeout(300);
      return false;
    }
  }
  return true;
}

// Check if input hash is matched with any 2-digit passcodes
// without havint to be in correct order.
async function hasAnyMatch(hash) {
  for (let i = 0; i < password_hash.length; i++) {
    if (hash === password_hash[i]) return true;
  }
  return false;
}

function SideChannel() {
  // make every 3rd one empty so it shows passcodes are 2-digit
  const [pwdString, setPwdString] = useState([null, null, ' ', null, null, ' ', null, null, ' ', null, null, ' ']);
  const [idx, setIdx] = useState(0);
  const [progress, setProgress] = useState(0);
  const [match, setMatch] = useState(-1); // -1: not tested, 0:wrong password, 1:correct password
  const [numMatch, setNumMatch] = useState(0); // -1: not tested, 0:wrong password, 1:correct password
  const [showButton, setShowButton] = useState(false); // Controls visibility of the green button
  const [isButtonDisabled, setIsButtonDisabled] = useState(false); // Controls if the button is disabled

  // Listen for sessionReset event
  useEffect(() => {
    const unsubscribeFromReset = subscribeToEvent('sessionReset', () => {
      console.log('Received sessionReset event in SideChannel component');
      setPwdString([null, null, ' ', null, null, ' ', null, null, ' ', null, null, ' ']);
      setIdx(0);
      setProgress(0);
      setMatch(-1);
      setNumMatch(0);
      setShowButton(false);
      setIsButtonDisabled(false);
    });

    return () => {
      unsubscribeFromReset();
    };
  }, []);

  if (admin) {
    console.log('Updating password hash');
    if (password.length === 8) {
      for (let i = 0; i < 4; i++) {
        let chars = password[i * 2].toUpperCase() + password[i * 2 + 1].toUpperCase();
        digestMessage(chars).then(digestHex => {
          password_hash[i] = digestHex;
          console.log(digestHex);
        });
      }
    }
  }

  // valid keys handler
  useEffect(() => {
    const handleKeyUp = e => {
      const nextpwdString = pwdString.slice();
      if (!showButton && e.key && e.key.toLowerCase && (VALID_CHARS.indexOf(e.key.toLowerCase()) >= 0 || SPECIAL_CHARS.indexOf(e.key.toLowerCase()) >= 0)) {
        let i = idx;
        if (i < pwdString.length) {
          nextpwdString[i] = e.key.toUpperCase();
          // if next idx is empty, then skip that idx and go to the next one
          if ((i + 1) % 3 === 2) {
            i += 1;
          }
          setIdx(i + 1);
        }
        setPwdString(nextpwdString);
      }
      // enter key handler -> start authenticate
      else if (!showButton && e.keyCode === 13 && (progress === 0 || progress === 100)) {
        setMatch(-1);
        setNumMatch(0);
        (async () => {
          await (async () => {
            setProgress(1);
            let matched = -1;
            let numMatched = 0;
            // i = character index of password string
            // j = j-th 2-digit code
            for (let i = 0, j = 0; i < pwdString.length; i += 3, j++) {
              let chars = pwdString[i] + pwdString[i + 1];
              await digestMessage(chars).then(async hash => {
                if (await isCorrectPass(hash, j)) {
                  setProgress((100 / (pwdString.length / 3)) * (j + 1));
                  console.log((100 / (pwdString.length / 3)) * (j + 1));
                } else {
                  setProgress((100 / (pwdString.length / 3)) * (j + 1));
                  console.log((100 / (pwdString.length / 3)) * (j + 1));
                  matched = 0;
                }
                if (await hasAnyMatch(hash)) {
                  numMatched++;
                  console.log('Match: ' + numMatched);
                }
              });
            }
            return [matched, numMatched];
          })().then(([matched, numMatched]) => {
            console.log('Matched:' + matched + ' numMatched:' + numMatched);
            setNumMatch(numMatched);
            if (matched !== 0) {
              setMatch(1);
              // Show the button after the animation is complete
              setTimeout(() => {
                setShowButton(true);
              }, 1000); // Wait for animation to complete
            } else setMatch(0);
          });
        })();
      }
    };

    window.document.addEventListener('keyup', handleKeyUp);
    return () => {
      window.document.removeEventListener('keyup', handleKeyUp);
    };
  }, [idx, setIdx, pwdString, setPwdString, match, setMatch, numMatch, setNumMatch]);

  // backspace, del key handler
  useEffect(() => {
    const handleKeyDown = e => {
      const nextpwdString = pwdString.slice();
      if (e.keyCode === 8 || e.keyCode === 46) {
        let i = idx;
        if ((i - 1) % 3 === 2) i -= 1;
        if (i > 0) {
          nextpwdString[i - 1] = null;
          setIdx(i - 1);
        }
      }
      setPwdString(nextpwdString);
    };

    window.document.addEventListener('keydown', handleKeyDown);
    return () => {
      window.document.removeEventListener('keydown', handleKeyDown);
    };
  }, [idx, setIdx, pwdString, setPwdString]);

  return (
    <div className={`SideChannel ${showButton ? 'overlay-active' : ''}`}>
      {showButton && (
        <div className='overlay'>
          <button
            className='success-button'
            disabled={isButtonDisabled}
            onClick={() => {
              console.log('Stop Timer button clicked');
              setIsButtonDisabled(true);

              // Use BroadcastChannel to notify all tabs to stop the timer
              broadcastEvent('stopTimer');

              // Get teamName from localStorage
              const teamName = localStorage.getItem('teamName');
              console.log('Team name:', teamName);

              // Wait a brief moment to allow the timer to update
              setTimeout(() => {
                // Get the timeLeft value from localStorage
                const timeLeft = localStorage.getItem('timeLeft');
                console.log('Time left:', timeLeft);

                // Calculate the time taken (GAME_TIME - timeLeft)
                const timeTaken = GAME_TIME * 60 - parseFloat(timeLeft);
                console.log('Time taken:', timeTaken);

                // Submit the data to the database
                if (teamName && timeLeft) {
                  fetch('https://escape-room-db-proxy.hursley-escape-room.workers.dev/submit', {
                    method: 'POST',
                    headers: {
                      'Content-Type': 'application/json',
                      Origin: window.location.origin,
                    },
                    body: JSON.stringify({
                      teamname: teamName,
                      time: timeTaken,
                      date: Math.floor(Date.now() / 1000), // Add current timestamp in seconds
                    }),
                  })
                    .then(response => {
                      if (!response.ok) {
                        throw new Error('Failed to submit score');
                      }
                      return response.text();
                    })
                    .then(data => {
                      console.log('Score submitted successfully:', data);
                    })
                    .catch(error => {
                      console.error('Error submitting score:', error);
                    });
                } else {
                  console.error('Missing team name or time left');
                }

                // Navigate to Intermission page after 5 seconds
                setTimeout(() => {
                  window.location.hash = '#intermission';
                }, 5000);
              }, 100); // Small delay to ensure timer has updated
            }}
          >
            {isButtonDisabled ? 'Timer Stopped!' : 'Unlocked! Safe Code: 74532A'}
          </button>
        </div>
      )}
      <div className={`content ${showButton ? 'blurred' : ''}`}>
        <div className='title'>
          <p>Password Verification System</p>
        </div>
        <header className='App-header'>
          <p>Type passcodes in the correct order</p>
        </header>
        <div className='msgLine input'>
          {pwdString.map((c, i) => (
            <div key={i} className={`${idx === i ? 'passcode empty' : 'passcode'} ${c === ' ' ? 'spaceChar' : ''}`}>
              {idx === i ? <div className='cursor'>_</div> : c}
            </div>
          ))}
        </div>
        <header className='App-header'>
          <p>{progress === 0 ? 'Press Enter to verify' : progress === 100 ? (match === 1 ? 'Correct' : 'Incorrect (' + (numMatch <= 1 ? numMatch + ' match' : numMatch + ' matches') + ')') : 'Verifying'}</p>
        </header>
        <div className='progressbar'>
          <div className={`${match === 1 ? 'success' : match === 0 ? 'fail' : 'progress'}`} style={{ width: `${progress}%` }}></div>
        </div>
      </div>
    </div>
  );
}

export default SideChannel;
